class Solution {
    fun minAreaRect(points:Array<IntArray>):Int{
        fun key(x:Int,y:Int):Long{
            return (x.toLong() shl 32) xor (y.toLong() and 0xffffffffL)
        };
        val set=points.map{
            key(it[0],it[1])
        }.toHashSet();
        var answer=Int.MAX_VALUE;
        for(i in points.indices)for(j in i+1 until points.size){
            val a=points[i];
            val b=points[j];
            if(a[0]==b[0]||a[1]==b[1])continue;
            if(key(a[0],b[1]) in set&&key(b[0],a[1]) in set)answer=minOf(answer,kotlin.math.abs(a[0]-b[0])*kotlin.math.abs(a[1]-b[1]))
        };
        return if(answer==Int.MAX_VALUE)0 else answer
    }
}

